); D -- 12 --&gt; C; E((E)) -- 50 --&gt; D; E -- 60 --&gt; C; E -- 10 --&gt; F((F)); F -- 15 --&gt; E; A -- 41 --&gt; F; B -- 70 --&gt; F; C -- 41 --&gt; F; 
