i = 0;
do {
 j = i + 1;
 while ((j &lt; n) &amp;&amp; E1) j++;
 if (j &lt; n) E2;
} while (j &lt; n);
flag = 1;
for (j = 0; j &lt; n; j++)
 if ((j != i) &amp;&amp; E3) flag = 0;
if (flag) printf("Sink exists");
else printf("Sink does not exist");

Choose the correct expression for $E_3$

- A. $(A[i][j] \;\&amp;\&amp;\; !A[j][i])$

C. $(!A[i][j] \;||\; A[j][i])$

- B. $(!A[i][j] \;\&amp;\&amp;\; A[j][i])$

D. $(A[i][j] \;||\; !A[j][i])$

